    static var lightThemes: [MewThemePalette] { all.filter { !$0.isDark } }
    static var darkThemes: [MewThemePalette] { all.filter(\.isDark) }

    static let defaultLightId: String = all.contains { $0.id == "codex-light" } ? "codex-light" : (lightThemes.first?.id ?? "codex-light")
    static let defaultDarkId: String = all.contains { $0.id == "codex-dark" } ? "codex-dark" : (darkThemes.first?.id ?? "codex-dark")

    static func palette(id: String, fallbackDark: Bool) -> MewThemePalette {
        if let match = all.first(where: { $0.id == id }) {
            return match
        }
        let fallbackId = fallbackDark ? defaultDarkId : defaultLightId
        return all.first(where: { $0.id == fallbackId }) ?? all[0]
    }
}

private extension Color {
    init(mewHex hex: UInt32) {
        let r = Double((hex >> 16) & 0xFF) / 255.0
        let g = Double((hex >> 8) & 0xFF) / 255.0
        let b = Double(hex & 0xFF) / 255.0
        self.init(.sRGB, red: r, green: g, blue: b, opacity: 1.0)
    }
}
